// Cap how many unique candidates we process each run (controls Claude cost)
const MAX_CANDIDATES = 5;

const seen = new Set();
const unique = [];

for (const item of $input.all()) {
  const data = item.json;
  // GitHub Search endpoints (/search/users, /search/repositories) wrap
  // results in { total_count, items: [...] }. Contributors/org-members
  // endpoints return a bare array (already split into items by n8n).
  const records = Array.isArray(data.items) ? data.items : [data];

  for (const rec of records) {
    if (!rec) continue;
    // Repository search returns repos; the person is rec.owner
    const person = rec.owner && rec.owner.login ? rec.owner : rec;
    // Skip organization / company accounts — we only want individual people.
    // GitHub marks org accounts with type === 'Organization'.
    if (person.type && String(person.type).toLowerCase() === 'organization') continue;
    const id = person.login || (person.id != null ? String(person.id) : null);
    if (id && !seen.has(id)) {
      seen.add(id);
      unique.push({ json: person });
    }
  }
}

return unique.slice(0, MAX_CANDIDATES);

// Get the profile data from the earlier node
const profile = $('Get Full Profile').first().json;

// Get the repos and format them as readable text
const repos = $('Get Their Repos').all().map(r => r.json);
const repoText = repos.map(r =>
  `${r.name} — ${r.stargazers_count} stars — ${r.language || 'unknown language'} — ${r.description || 'no description'}`
).join('\n');

// Package everything together
return [{
  json: {
    login: profile.login,
    name: profile.name || profile.login,
    bio: profile.bio || 'no bio',
    company: (profile.company || 'unknown').replace('@', ''),
    location: profile.location || 'unknown',
    followers: profile.followers,
    public_repos: profile.public_repos,
    hireable: profile.hireable === true ? 'YES - marked as available' : 'not marked',
    github_url: profile.html_url,
    top_repos: repoText || 'no public repos'
  }
}];

