// Grab Claude's text output. With simplify:true the Anthropic node returns
// content as an array of blocks like [{ type: 'text', text: '...' }].
const raw = $json.content ?? $json.text ?? $json.message ?? $json.output ?? '';
let text;
if (Array.isArray(raw)) {
  // Concatenate the text of all text blocks
  text = raw.map(b => (b && typeof b === 'object' ? (b.text || '') : String(b))).join('');
} else if (raw && typeof raw === 'object') {
  text = raw.text || JSON.stringify(raw);
} else {
  text = String(raw);
}

// Strip any accidental markdown code fences
text = text.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  // Try to extract the first JSON object from the text
  const match = text.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : { score: 0, strengths: '', gaps: 'Could not parse AI response', outreach_hook: '' };
}

const profile = $('Format for Claude').first().json;

return [{
  json: {
    login: profile.login,
    name: profile.name,
    company: profile.company,
    location: profile.location,
    followers: profile.followers,
    public_repos: profile.public_repos,
    hireable: profile.hireable,
    github_url: profile.github_url,
    top_repos: profile.top_repos,
    score: Number(parsed.score) || 0,
    strengths: parsed.strengths || '',
    gaps: parsed.gaps || '',
    outreach_hook: parsed.outreach_hook || ''
  }
}];
